head.script:
/**/
    (function () {
      try {
        var d = document.documentElement, s = window.localStorage;
        var m = s.getItem('mw.mode') || 'auto';
        var dark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
        d.setAttribute('data-mode', m === 'auto' ? (dark ? 'dark' : 'light') : m);
        d.setAttribute('data-mode-pref', m);
        d.setAttribute('data-accent', s.getItem('mw.accent') || 'blue');
        var l = s.getItem('mw.lang');
        if (l) {
          d.setAttribute('lang', l);
          d.setAttribute('dir', (l === 'ar' || l === 'ur') ? 'rtl' : 'ltr');
        }
      } catch (e) {}
    })();
  /**/

head.b:skin:
/*
<Group description="ModWeeb — الألوان" selector="html">
  <Variable name="keycolor" description="لون السمة الأساسي" type="color" default="#3b82f6" value="#3b82f6"/>
  <Variable name="accent.soft" description="خلفية السمة الفاتحة" type="color" default="#eff6ff" value="#eff6ff"/>
  <Variable name="body.background" description="خلفية الصفحة" type="color" default="#f9fafb" value="#f9fafb"/>
  <Variable name="card.background" description="خلفية البطاقات" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="card.alt" description="خلفية داخلية ثانوية" type="color" default="#f6f6f6" value="#f6f6f6"/>
  <Variable name="heading.color" description="لون العناوين" type="color" default="#111827" value="#111827"/>
  <Variable name="body.textColor" description="لون النص" type="color" default="#1f2937" value="#1f2937"/>
  <Variable name="muted.color" description="لون النص الثانوي" type="color" default="#6b7280" value="#6b7280"/>
  <Variable name="border.color" description="لون الحدود" type="color" default="#e5e7eb" value="#e5e7eb"/>
</Group>
<Group description="ModWeeb — الخطوط والأبعاد" selector="html">
  <Variable name="font.body" description="خط النص" type="font" default="normal normal 16px 'IBM Plex Sans Arabic', system-ui, sans-serif" value="normal normal 16px 'IBM Plex Sans Arabic', system-ui, sans-serif"/>
  <Variable name="font.heading" description="خط العناوين" type="font" default="normal bold 16px 'IBM Plex Sans Arabic', system-ui, sans-serif" value="normal bold 16px 'IBM Plex Sans Arabic', system-ui, sans-serif"/>
  <Variable name="content.width" description="عرض المحتوى" type="length" default="1180px" min="960px" max="1440px"/>
  <Variable name="radius.base" description="انحناء البطاقات" type="length" default="14px" min="0px" max="24px"/>
  <Variable name="header.height" description="ارتفاع الهيدر" type="length" default="64px" min="52px" max="84px"/>
</Group>
*/

/* =========================================================
   ModWeeb Theme — Blogger template
   Design tokens shared with the ModWeeb tools hub.
   ========================================================= */

:root {
  /* brand defaults (Theme Designer overrides via $()) */
  --mw-accent: $(keycolor);
  --mw-accent-soft: $(accent.soft);
  --mw-bg: $(body.background);
  --mw-card: $(card.background);
  --mw-card-alt: $(card.alt);
  --mw-heading: $(heading.color);
  --mw-text: $(body.textColor);
  --mw-muted: $(muted.color);
  --mw-border: $(border.color);

  --mw-on-accent: #ffffff;
  --mw-glass: color-mix(in srgb, var(--mw-card) 72%, transparent);
  --mw-shadow-sm: 0 1px 2px rgb(0 0 0 / .04), 0 1px 3px rgb(0 0 0 / .05);
  --mw-shadow-md: 0 6px 24px rgb(0 0 0 / .06);
  --mw-shadow-lg: 0 18px 48px rgb(0 0 0 / .10);

  --mw-radius: $(radius.base);
  --mw-radius-sm: 8px;
  --mw-radius-pill: 999px;

  --mw-font: $(font.body);
  --mw-font-heading: $(font.heading);
  --mw-font-mono: ui-monospace, 'JetBrains Mono', 'Cascadia Code', 'Courier New', monospace;

  --mw-width: $(content.width);
  --mw-prose-width: 760px;
  --mw-header-h: $(header.height);
  --mw-gap: clamp(16px, 2.4vw, 28px);
  --mw-pad: clamp(16px, 3vw, 32px);

  --mw-ease: cubic-bezier(.2, .7, .3, 1);
  --mw-dur: .22s;

  /* semantic status colors */
  --mw-info: #3b82f6;
  --mw-warning: #d97706;
  --mw-success: #16a34a;
  --mw-error: #dc2626;
  --mw-tip: #7c3aed;

  color-scheme: light;
}

/* ---------- Dark mode ---------- */
html[data-mode="dark"] {
  --mw-bg: #1a1a1a;
  --mw-card: #252526;
  --mw-card-alt: #2d2d2e;
  --mw-heading: #f5f5f5;
  --mw-text: #e5e5e5;
  --mw-muted: #a1a1aa;
  --mw-border: #3a3a3b;
  --mw-on-accent: #111827;
  --mw-glass: color-mix(in srgb, #1f1f20 74%, transparent);
  --mw-shadow-sm: 0 1px 2px rgb(0 0 0 / .35);
  --mw-shadow-md: 0 8px 28px rgb(0 0 0 / .45);
  --mw-shadow-lg: 0 20px 50px rgb(0 0 0 / .55);
  --mw-info: #60a5fa;
  --mw-warning: #fbbf24;
  --mw-success: #4ade80;
  --mw-error: #f87171;
  --mw-tip: #c084fc;
  color-scheme: dark;
}

/* ---------- Soft mode (accent-tinted light) ---------- */
html[data-mode="soft"] {
  --mw-bg: color-mix(in srgb, var(--mw-accent) 7%, #ffffff);
  --mw-card: #ffffff;
  --mw-card-alt: color-mix(in srgb, var(--mw-accent) 5%, #f7f7f7);
  --mw-border: color-mix(in srgb, var(--mw-accent) 16%, #e5e7eb);
  --mw-glass: color-mix(in srgb, #ffffff 70%, transparent);
}

/* ---------- Accent palettes (light / soft / dark) ---------- */
html[data-accent="blue"]    { --mw-accent: #3b82f6; --mw-accent-soft: #eff6ff; }
html[data-accent="violet"]  { --mw-accent: #6d28d9; --mw-accent-soft: #f5f3ff; }
html[data-accent="teal"]    { --mw-accent: #0f766e; --mw-accent-soft: #f0fdfa; }
html[data-accent="emerald"] { --mw-accent: #15803d; --mw-accent-soft: #f0fdf4; }
html[data-accent="rose"]    { --mw-accent: #be123c; --mw-accent-soft: #fff1f2; }
html[data-accent="amber"]   { --mw-accent: #b45309; --mw-accent-soft: #fffbeb; }

html[data-mode="dark"][data-accent="blue"]    { --mw-accent: #41a2ef; --mw-accent-soft: rgb(65 162 239 / .14); }
html[data-mode="dark"][data-accent="violet"]  { --mw-accent: #c084fc; --mw-accent-soft: rgb(192 132 252 / .14); }
html[data-mode="dark"][data-accent="teal"]    { --mw-accent: #2dd4bf; --mw-accent-soft: rgb(45 212 191 / .14); }
html[data-mode="dark"][data-accent="emerald"] { --mw-accent: #4ade80; --mw-accent-soft: rgb(74 222 128 / .14); }
html[data-mode="dark"][data-accent="rose"]    { --mw-accent: #fb7185; --mw-accent-soft: rgb(251 113 133 / .14); }
html[data-mode="dark"][data-accent="amber"]   { --mw-accent: #fbbf24; --mw-accent-soft: rgb(251 191 36 / .14); }

html[data-mode="soft"][data-accent="blue"]    { --mw-accent: #2563eb; }
html[data-mode="soft"][data-accent="violet"]  { --mw-accent: #6d28d9; }
html[data-mode="soft"][data-accent="teal"]    { --mw-accent: #0f766e; }
html[data-mode="soft"][data-accent="emerald"] { --mw-accent: #15803d; }
html[data-mode="soft"][data-accent="rose"]    { --mw-accent: #be123c; }
html[data-mode="soft"][data-accent="amber"]   { --mw-accent: #b45309; }

/* =========================================================
   Base
   ========================================================= */
*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--mw-header-h) + 18px);
  background: var(--mw-bg);
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--mw-bg);
  color: var(--mw-text);
  font: var(--mw-font);
  font-size: 16px;
  line-height: 1.8;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

html[dir="rtl"] body { text-align: right; }

h1, h2, h3, h4, h5, h6 {
  margin: 0 0 .5em;
  color: var(--mw-heading);
  font-family: var(--mw-font-heading);
  font-weight: 700;
  line-height: 1.35;
  text-wrap: balance;
}

p { margin: 0 0 1em; }
a { color: var(--mw-accent); text-decoration: none; transition: color var(--mw-dur) var(--mw-ease); }
a:hover { color: color-mix(in srgb, var(--mw-accent) 78%, var(--mw-heading)); }
img, svg, video, iframe { max-width: 100%; }
img { height: auto; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
ul, ol { padding-inline-start: 1.35em; }
hr { border: 0; border-top: 1px solid var(--mw-border); margin: 2rem 0; }
::selection { background: color-mix(in srgb, var(--mw-accent) 26%, transparent); color: var(--mw-heading); }
:focus-visible { outline: 2px solid var(--mw-accent); outline-offset: 2px; border-radius: 4px; }

.icon { width: 1.15em; height: 1.15em; flex: 0 0 auto; stroke: currentColor; fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.icon-fill { fill: currentColor; stroke: none; }
.visually-hidden {
  position: absolute !important; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip-link {
  position: fixed; inset-block-start: 10px; inset-inline-start: 50%;
  transform: translate(-50%, -160%);
  z-index: 2000; padding: .6rem 1.1rem; border-radius: var(--mw-radius-pill);
  background: var(--mw-accent); color: var(--mw-on-accent); font-weight: 600;
  transition: transform .2s var(--mw-ease);
}
.skip-link:focus { transform: translate(-50%, 0); color: var(--mw-on-accent); }

.container { width: min(100% - 2 * var(--mw-pad), var(--mw-width)); margin-inline: auto; }
.section { padding-block: clamp(28px, 5vw, 56px); }
.section + .section { border-top: 1px solid color-mix(in srgb, var(--mw-border) 65%, transparent); }

/* =========================================================
   Header
   ========================================================= */
.site-header {
  position: sticky; inset-block-start: 0; z-index: 900;
  background: var(--mw-glass);
  -webkit-backdrop-filter: saturate(1.4) blur(14px);
  backdrop-filter: saturate(1.4) blur(14px);
  border-block-end: 1px solid color-mix(in srgb, var(--mw-border) 70%, transparent);
  transition: box-shadow var(--mw-dur) var(--mw-ease), background var(--mw-dur) var(--mw-ease);
}
.site-header.is-scrolled { box-shadow: var(--mw-shadow-sm); }

.header-inner {
  min-height: var(--mw-header-h);
  display: flex; align-items: center; gap: clamp(8px, 1.6vw, 18px);
}

.brand { display: inline-flex; align-items: center; gap: .6rem; min-width: 0; color: var(--mw-heading); }
.brand:hover { color: var(--mw-heading); }
.brand-logo { width: 34px; height: 34px; flex: 0 0 34px; border-radius: 22%; background: #fff; box-shadow: 0 0 0 1px color-mix(in srgb, var(--mw-border) 70%, transparent); }
.brand-text { display: flex; flex-direction: column; line-height: 1.15; min-width: 0; }
.brand-title { font-weight: 700; font-size: 1rem; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.brand-desc { font-size: .72rem; color: var(--mw-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.main-nav { margin-inline-start: auto; }
.main-nav ul { display: flex; align-items: center; gap: 2px; margin: 0; padding: 0; list-style: none; }
.main-nav a {
  display: inline-flex; align-items: center; gap: .4rem;
  padding: .38rem .7rem; border-radius: var(--mw-radius-pill);
  color: var(--mw-muted); font-size: .86rem; font-weight: 500; white-space: nowrap;
}
.main-nav a:hover { color: var(--mw-heading); background: var(--mw-card-alt); }
.main-nav .selected a { color: var(--mw-accent); background: var(--mw-accent-soft); }

.header-actions { display: flex; align-items: center; gap: 6px; }

.icon-btn {
  position: relative;
  display: inline-grid; place-items: center;
  width: 34px; height: 34px; padding: 0;
  border: 1px solid transparent; border-radius: 50%;
  background: transparent; color: var(--mw-muted);
  transition: color var(--mw-dur) var(--mw-ease), background var(--mw-dur) var(--mw-ease), border-color var(--mw-dur) var(--mw-ease);
}
.icon-btn:hover { color: var(--mw-accent); background: var(--mw-accent-soft); }
.icon-btn[aria-expanded="true"] { color: var(--mw-on-accent); background: var(--mw-accent); border-color: var(--mw-accent); }
.icon-btn .icon { width: 18px; height: 18px; }
.icon-btn.is-accent { color: var(--mw-on-accent); background: var(--mw-accent); border-color: var(--mw-accent); }
.icon-btn.is-accent:hover { background: color-mix(in srgb, var(--mw-accent) 88%, #000); }

.menu-btn { display: none; }

/* mobile nav */
.nav-toggle { display: none; }
@media (max-width: 900px) {
  .menu-btn { display: inline-grid; }
  .main-nav {
    position: fixed; inset-block-start: var(--mw-header-h); inset-inline: 0;
    margin: 0; padding: 10px var(--mw-pad) 18px;
    background: var(--mw-card); border-block-end: 1px solid var(--mw-border);
    box-shadow: var(--mw-shadow-md);
    transform: translateY(-8px); opacity: 0; pointer-events: none;
    transition: opacity var(--mw-dur) var(--mw-ease), transform var(--mw-dur) var(--mw-ease);
    max-height: calc(100vh - var(--mw-header-h)); overflow: auto;
  }
  .main-nav.is-open { opacity: 1; transform: none; pointer-events: auto; }
  .main-nav ul { flex-direction: column; align-items: stretch; gap: 2px; }
  .main-nav a { padding: .6rem .75rem; border-radius: var(--mw-radius-sm); font-size: .95rem; }
}

/* search */
.site-search {
  position: fixed; inset-block-start: var(--mw-header-h); inset-inline: 0; z-index: 880;
  background: var(--mw-card); border-block-end: 1px solid var(--mw-border);
  box-shadow: var(--mw-shadow-md); padding: 12px var(--mw-pad) 16px;
  transform: translateY(-10px); opacity: 0; pointer-events: none;
  transition: opacity var(--mw-dur) var(--mw-ease), transform var(--mw-dur) var(--mw-ease);
}
.site-search.is-open { opacity: 1; transform: none; pointer-events: auto; }
.search-form { display: flex; gap: 8px; width: min(100%, 680px); margin-inline: auto; }
.search-form input[type="search"] {
  flex: 1; min-width: 0; padding: .55rem .9rem;
  border: 1px solid var(--mw-border); border-radius: var(--mw-radius-pill);
  background: var(--mw-card-alt); color: var(--mw-text);
}
.search-form input[type="search"]:focus { border-color: var(--mw-accent); background: var(--mw-card); outline: none; box-shadow: 0 0 0 3px color-mix(in srgb, var(--mw-accent) 18%, transparent); }
.search-form button {
  display: inline-flex; align-items: center; gap: .4rem;
  padding: .55rem 1rem; border: 0; border-radius: var(--mw-radius-pill);
  background: var(--mw-accent); color: var(--mw-on-accent); font-weight: 600; font-size: .88rem;
}

/* popovers */
.popover {
  position: absolute; z-index: 950; inset-block-start: calc(100% + 10px);
  min-width: 232px; padding: 10px;
  background: var(--mw-card); border: 1px solid var(--mw-border);
  border-radius: var(--mw-radius); box-shadow: var(--mw-shadow-lg);
  opacity: 0; transform: translateY(-6px); pointer-events: none;
  transition: opacity var(--mw-dur) var(--mw-ease), transform var(--mw-dur) var(--mw-ease);
}
.popover.is-open { opacity: 1; transform: none; pointer-events: auto; }
html[dir="rtl"] .popover { inset-inline-end: 0; }
html[dir="ltr"] .popover { inset-inline-start: 0; }
.popover-anchor { position: relative; }

.popover-title { margin: 2px 4px 8px; font-size: .72rem; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--mw-muted); }

.swatch-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.swatch {
  position: relative; height: 30px; padding: 0; border: 1px solid var(--mw-border);
  border-radius: var(--mw-radius-sm); background: var(--swatch); cursor: pointer;
  transition: transform var(--mw-dur) var(--mw-ease), box-shadow var(--mw-dur) var(--mw-ease);
}
.swatch:hover { transform: translateY(-1px); box-shadow: var(--mw-shadow-sm); }
.swatch[aria-pressed="true"]::after {
  content: ""; position: absolute; inset: 0; margin: auto;
  width: 8px; height: 8px; border-radius: 50%; background: #fff;
  box-shadow: 0 0 0 2px rgb(0 0 0 / .18);
}

.seg {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px;
  margin-block-start: 10px; padding: 3px;
  background: var(--mw-card-alt); border: 1px solid var(--mw-border); border-radius: var(--mw-radius-sm);
}
.seg button {
  display: inline-flex; align-items: center; justify-content: center; gap: 4px;
  padding: .32rem .2rem; border: 0; border-radius: 6px; background: transparent;
  color: var(--mw-muted); font-size: .74rem; font-weight: 600;
}
.seg button .icon { width: 14px; height: 14px; }
.seg button[aria-pressed="true"] { background: var(--mw-card); color: var(--mw-accent); box-shadow: var(--mw-shadow-sm); }

.menu-list { display: grid; gap: 2px; margin: 0; padding: 0; list-style: none; }
.menu-list button, .menu-list a {
  display: flex; align-items: center; gap: .55rem; width: 100%;
  padding: .45rem .6rem; border: 0; border-radius: var(--mw-radius-sm);
  background: transparent; color: var(--mw-text); font-size: .86rem; text-align: start;
}
.menu-list button:hover, .menu-list a:hover { background: var(--mw-card-alt); color: var(--mw-heading); }
.menu-list button[aria-pressed="true"] { color: var(--mw-accent); background: var(--mw-accent-soft); font-weight: 600; }
.menu-list .icon { width: 16px; height: 16px; color: var(--mw-muted); }

/* reading progress */
.reading-progress {
  position: fixed; inset-block-start: 0; inset-inline: 0; z-index: 1000;
  height: 2px; background: transparent; pointer-events: none;
}
.reading-progress span {
  display: block; height: 100%; width: 0;
  background: linear-gradient(90deg, var(--mw-accent), color-mix(in srgb, var(--mw-accent) 55%, #fff));
  transition: width .1s linear;
}

/* =========================================================
   Home: hero / featured / grids
   ========================================================= */
.page-head { padding-block: clamp(22px, 4vw, 40px) 6px; }
.page-head h1 { font-size: clamp(1.5rem, 3.4vw, 2.1rem); margin-bottom: .25rem; }
.page-head p { color: var(--mw-muted); max-width: 62ch; margin: 0; font-size: .95rem; }

.section-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-block-end: 18px; }
.section-head h2 { font-size: 1.15rem; margin: 0; display: inline-flex; align-items: center; gap: .5rem; }
.section-head h2::before { content: ""; width: 3px; height: 1.05em; border-radius: 2px; background: var(--mw-accent); }
.section-head p { margin: .2rem 0 0; color: var(--mw-muted); font-size: .85rem; }
.section-head a { font-size: .82rem; font-weight: 600; white-space: nowrap; }

.featured {
  display: grid; grid-template-columns: 1.15fr .85fr; gap: 0;
  overflow: hidden; border: 1px solid var(--mw-border); border-radius: var(--mw-radius);
  background: var(--mw-card); box-shadow: var(--mw-shadow-sm);
}
.featured-media { position: relative; min-height: 260px; background: var(--mw-card-alt); }
.featured-media img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.featured-body { padding: clamp(18px, 3vw, 32px); display: flex; flex-direction: column; gap: 10px; justify-content: center; }
.featured-body h2 { font-size: clamp(1.25rem, 2.6vw, 1.7rem); margin: 0; }
.featured-body h2 a { color: var(--mw-heading); }
.featured-body h2 a:hover { color: var(--mw-accent); }
.featured-body .excerpt { color: var(--mw-muted); font-size: .92rem; margin: 0; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.featured-badge { align-self: flex-start; }

.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 280px), 1fr)); gap: var(--mw-gap); }
.cards.cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.cards.cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.card {
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--mw-card); border: 1px solid var(--mw-border);
  border-radius: var(--mw-radius); box-shadow: var(--mw-shadow-sm);
  transition: transform var(--mw-dur) var(--mw-ease), box-shadow var(--mw-dur) var(--mw-ease), border-color var(--mw-dur) var(--mw-ease);
}
.card:hover { transform: translateY(-2px); box-shadow: var(--mw-shadow-md); border-color: color-mix(in srgb, var(--mw-accent) 30%, var(--mw-border)); }
.card-media { position: relative; aspect-ratio: 16 / 9; background: var(--mw-card-alt); overflow: hidden; }
.card-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s var(--mw-ease); }
.card:hover .card-media img { transform: scale(1.03); }
.card-body { display: flex; flex-direction: column; gap: 8px; padding: 16px 18px 18px; flex: 1; }
.card-title { font-size: 1rem; line-height: 1.5; margin: 0; }
.card-title a { color: var(--mw-heading); }
.card-title a:hover { color: var(--mw-accent); }
.card-excerpt { margin: 0; color: var(--mw-muted); font-size: .84rem; line-height: 1.7; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.card-foot { margin-block-start: auto; display: flex; align-items: center; justify-content: space-between; gap: 10px; padding-block-start: 4px; }

.byline { display: inline-flex; align-items: center; gap: .45rem; min-width: 0; font-size: .76rem; color: var(--mw-muted); }
.byline img, .byline .avatar { width: 22px; height: 22px; flex: 0 0 22px; border-radius: 50%; object-fit: cover; background: var(--mw-accent-soft); }
.byline .name { color: var(--mw-text); font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.byline .dot::before { content: "·"; margin-inline: .15rem; }

.meta-line { display: inline-flex; align-items: center; gap: .4rem; font-size: .76rem; color: var(--mw-muted); }
.meta-line .icon { width: 14px; height: 14px; }

.chip {
  display: inline-flex; align-items: center; gap: .3rem;
  padding: .18rem .55rem; border-radius: var(--mw-radius-pill);
  background: var(--mw-accent-soft); color: var(--mw-accent);
  font-size: .72rem; font-weight: 600; line-height: 1.5;
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.chip:hover { color: var(--mw-on-accent); background: var(--mw-accent); }
.chip .hash { opacity: .55; font-weight: 500; }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }

.badge {
  display: inline-flex; align-items: center; gap: .3rem;
  padding: .2rem .6rem; border-radius: var(--mw-radius-pill);
  font-size: .7rem; font-weight: 700; letter-spacing: .02em;
  background: var(--mw-accent); color: var(--mw-on-accent);
}
.badge.soft { background: var(--mw-accent-soft); color: var(--mw-accent); }

.pagination { display: flex; align-items: center; justify-content: center; gap: 10px; margin-block-start: 28px; }
.pagination a, .pagination span {
  display: inline-flex; align-items: center; gap: .4rem;
  padding: .5rem .95rem; border: 1px solid var(--mw-border); border-radius: var(--mw-radius-pill);
  background: var(--mw-card); color: var(--mw-text); font-size: .84rem; font-weight: 600;
}
.pagination a:hover { border-color: var(--mw-accent); color: var(--mw-accent); }

/* =========================================================
   Labels / tags
   ========================================================= */
.tag-cloud { display: flex; flex-wrap: wrap; gap: 8px; }
.tag-cloud a {
  display: inline-flex; align-items: center; gap: .35rem;
  padding: .35rem .8rem; border: 1px solid var(--mw-border); border-radius: var(--mw-radius-pill);
  background: var(--mw-card); color: var(--mw-text); font-size: .82rem; font-weight: 500;
}
.tag-cloud a:hover { border-color: var(--mw-accent); color: var(--mw-accent); background: var(--mw-accent-soft); }
.tag-cloud a .count { font-size: .7rem; color: var(--mw-muted); }
.tag-cloud a:hover .count { color: var(--mw-accent); }

/* =========================================================
   Article
   ========================================================= */
.article-wrap { padding-block: clamp(20px, 3vw, 36px) clamp(32px, 5vw, 64px); }
.breadcrumb { display: flex; align-items: center; flex-wrap: wrap; gap: .35rem; font-size: .78rem; color: var(--mw-muted); margin-block-end: 14px; }
.breadcrumb a { color: var(--mw-muted); display: inline-flex; align-items: center; gap: .25rem; }
.breadcrumb a:hover { color: var(--mw-accent); }
.breadcrumb .sep { opacity: .6; }
.breadcrumb [aria-current="page"] { color: var(--mw-text); font-weight: 600; max-width: 60ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.article-header { max-width: var(--mw-prose-width); }
.article-header h1 { font-size: clamp(1.6rem, 4vw, 2.35rem); line-height: 1.3; margin-block: 6px 14px; letter-spacing: -.015em; }
.article-meta { display: flex; align-items: center; flex-wrap: wrap; gap: .55rem 1rem; color: var(--mw-muted); font-size: .82rem; padding-block: 4px 2px; }
.article-meta .byline img { width: 30px; height: 30px; flex-basis: 30px; }
.article-meta .byline .name { font-size: .86rem; }
.article-meta .meta-line { font-size: .8rem; }
.article-labels { margin-block-start: 10px; }

.article-hero { margin-block: clamp(18px, 3vw, 28px) 0; border-radius: var(--mw-radius); overflow: hidden; border: 1px solid var(--mw-border); background: var(--mw-card-alt); }
.article-hero img { display: block; width: 100%; aspect-ratio: 16 / 9; object-fit: cover; }

.page-grid { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: clamp(24px, 4vw, 48px); align-items: start; }
.page-main { min-width: 0; }
.article-main { min-width: 0; }
.article-side { position: sticky; inset-block-start: calc(var(--mw-header-h) + 18px); display: grid; gap: 16px; }

.article-footer { max-width: var(--mw-prose-width); margin-block-start: 28px; }
.share-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding-block: 16px; border-block: 1px solid var(--mw-border); }
.share-bar .label { font-size: .8rem; font-weight: 600; color: var(--mw-muted); margin-inline-end: 4px; }
.share-btn {
  display: inline-grid; place-items: center; width: 34px; height: 34px;
  border: 1px solid var(--mw-border); border-radius: 50%;
  background: var(--mw-card); color: var(--mw-muted);
}
.share-btn:hover { color: var(--mw-accent); border-color: var(--mw-accent); background: var(--mw-accent-soft); }
.share-btn .icon { width: 16px; height: 16px; }
.share-btn.copied { color: var(--mw-success); border-color: var(--mw-success); }

.post-nav { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-block-start: 22px; }
.post-nav a {
  display: flex; flex-direction: column; gap: 4px;
  padding: 14px 16px; border: 1px solid var(--mw-border); border-radius: var(--mw-radius-sm);
  background: var(--mw-card); color: var(--mw-text); min-width: 0;
}
.post-nav a:hover { border-color: var(--mw-accent); }
.post-nav .dir { font-size: .72rem; color: var(--mw-muted); display: inline-flex; align-items: center; gap: .3rem; }
.post-nav .t { font-weight: 600; font-size: .88rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.post-nav .next { text-align: end; }
.post-nav .next .dir { justify-content: flex-end; }

/* related */
.related { margin-block-start: clamp(28px, 4vw, 44px); }

/* comments */
.comments-wrap { margin-block-start: clamp(28px, 4vw, 44px); padding-block-start: 22px; border-block-start: 1px solid var(--mw-border); max-width: var(--mw-prose-width); }
.comments-wrap h2 { font-size: 1.1rem; display: flex; align-items: center; gap: .5rem; }
.comments-wrap .comment-count { font-size: .75rem; color: var(--mw-muted); font-weight: 500; }
.comment-form iframe { border: 0; width: 100%; border-radius: var(--mw-radius-sm); }
.comment-thread { list-style: none; padding: 0; margin: 0; display: grid; gap: 12px; }
.comment-thread .comment { padding: 14px 16px; border: 1px solid var(--mw-border); border-radius: var(--mw-radius-sm); background: var(--mw-card); }
.comment-thread .comment .comment { background: var(--mw-card-alt); }
.comment-thread .comment-header { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem; font-size: .8rem; color: var(--mw-muted); margin-block-end: 6px; }
.comment-thread .comment-header cite { font-style: normal; font-weight: 700; color: var(--mw-heading); }
.comment-thread .comment-content { font-size: .9rem; }
.comment-thread .comment-content p:last-child { margin-bottom: 0; }
.comment-thread .comment-actions { display: flex; gap: 10px; margin-block-start: 8px; font-size: .75rem; }
.comment-thread .comment-actions a { color: var(--mw-muted); }
.comment-thread .comment-actions a:hover { color: var(--mw-accent); }
.comment-paging { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-block-end: 12px; font-size: .8rem; }
.comment-paging a { padding: .25rem .6rem; border: 1px solid var(--mw-border); border-radius: var(--mw-radius-pill); color: var(--mw-text); }

/* =========================================================
   Prose — article generator elements
   ========================================================= */
.prose {
  max-width: var(--mw-prose-width);
  color: var(--mw-text);
  font-size: 1.0625rem;
  line-height: 1.9;
  overflow-wrap: anywhere;
}
.prose > :first-child { margin-block-start: 0; }
.prose > :last-child { margin-block-end: 0; }

.prose :is(h1, h2, h3, h4, h5, h6) {
  margin-block: 1.7em .65em;
  color: var(--mw-heading);
  font-weight: 700;
  line-height: 1.4;
  scroll-margin-block-start: calc(var(--mw-header-h) + 20px);
}
.prose h1 { font-size: clamp(1.6rem, 4vw, 2rem); }
.prose h2 { font-size: clamp(1.32rem, 3.2vw, 1.6rem); padding-block-end: .3em; border-block-end: 1px solid var(--mw-border); }
.prose h3 { font-size: 1.22rem; }
.prose h4 { font-size: 1.08rem; }
.prose h5 { font-size: 1rem; }
.prose h6 { font-size: .92rem; color: var(--mw-muted); }

/* visual heading prefix/suffix generated by the article tool */
.prose :is(h1, h2, h3, h4, h5, h6)[data-before]::before { content: attr(data-before); color: var(--mw-accent); margin-inline-end: .35em; font-weight: 700; }
.prose :is(h1, h2, h3, h4, h5, h6)[data-after]::after { content: attr(data-after); color: var(--mw-accent); margin-inline-start: .35em; font-weight: 700; }

.prose p { margin-block: 1.1em; color: color-mix(in srgb, var(--mw-text) 90%, transparent); text-wrap: pretty; }
.prose a {
  color: var(--mw-accent); font-weight: 600;
  text-decoration: underline; text-decoration-thickness: 1px;
  text-decoration-color: color-mix(in srgb, var(--mw-accent) 40%, transparent);
  text-underline-offset: 3px;
}
.prose a:hover { text-decoration-color: currentColor; }
.prose :is(strong, b) { color: var(--mw-heading); font-weight: 700; }
.prose em { color: var(--mw-text); }
.prose :is(ul, ol) { margin-block: 1.2em; padding-inline-start: 1.5rem; }
.prose ul { list-style: disc; }
.prose ol { list-style: decimal; }
.prose li { margin-block: .4em; padding-inline-start: .15rem; }
.prose li::marker { color: var(--mw-muted); }
.prose :is(ul ul, ol ol, ul ol, ol ul) { margin-block: .4em; }
.prose ul.s1 { list-style: none; padding-inline-start: 0; }
.prose ul.s1 > li { position: relative; padding-inline-start: 1.4rem; }
.prose ul.s1 > li::before {
  content: ""; position: absolute; inset-inline-start: .2rem; inset-block-start: .75em;
  width: 7px; height: 7px; border-radius: 50%; background: var(--mw-accent);
}

.prose :not(pre) > code {
  padding: .12em .4em; border: 1px solid var(--mw-border); border-radius: 5px;
  background: var(--mw-card-alt); color: var(--mw-heading);
  font-family: var(--mw-font-mono); font-size: .86em;
}
.prose pre {
  position: relative;
  max-width: 100%; max-height: min(70vh, 900px);
  margin-block: 1.4rem; padding: 2.4rem 1rem 1rem;
  overflow: auto; border: 1px solid var(--mw-border); border-radius: var(--mw-radius-sm);
  background: var(--mw-card-alt); color: var(--mw-text);
  direction: ltr; text-align: left; tab-size: 2;
}
.prose pre code { padding: 0; border: 0; background: transparent; color: inherit; font-family: var(--mw-font-mono); font-size: .84rem; line-height: 1.75; white-space: pre; }
.prose pre[data-source]::before,
.prose pre[data-comment]::before {
  content: attr(data-source); position: absolute; inset-block-start: 0; inset-inline: 0;
  padding: .3rem .9rem; font: 500 .72rem/1.6 var(--mw-font-mono);
  color: var(--mw-muted); background: color-mix(in srgb, var(--mw-border) 30%, var(--mw-card-alt));
  border-block-end: 1px solid var(--mw-border);
}
.prose pre[data-comment]::before { content: attr(data-comment); }
.copy-code {
  position: absolute; inset-block-start: 4px; inset-inline-end: 6px; z-index: 2;
  display: inline-grid; place-items: center; width: 26px; height: 26px;
  border: 1px solid var(--mw-border); border-radius: 6px; background: var(--mw-card); color: var(--mw-muted);
}
.copy-code:hover { color: var(--mw-accent); border-color: var(--mw-accent); }
.copy-code .icon { width: 14px; height: 14px; }
.prose pre:has([data-source]) .copy-code, .prose pre:has([data-comment]) .copy-code { inset-block-start: 34px; }

/* code tabs from the generator */
.prose .pre.tabs { margin-block: 1.4rem; border: 1px solid var(--mw-border); border-radius: var(--mw-radius-sm); overflow: hidden; background: var(--mw-card-alt); }
.prose .pre.tabs > input { position: absolute; opacity: 0; pointer-events: none; }
.prose .pre.tabs > div:first-of-type { display: flex; gap: 2px; padding: 6px 6px 0; background: color-mix(in srgb, var(--mw-border) 26%, var(--mw-card-alt)); border-block-end: 1px solid var(--mw-border); }
.prose .pre.tabs label {
  padding: .35rem .85rem; border-radius: 6px 6px 0 0; cursor: pointer;
  font: 600 .78rem/1.5 var(--mw-font-mono); color: var(--mw-muted);
}
.prose .pre.tabs label::before { content: attr(data-text); }
.prose .pre.tabs label[data-tab-active] { background: var(--mw-card-alt); color: var(--mw-accent); }
.prose .pre.tabs pre { margin: 0; border: 0; border-radius: 0; }
.prose .pre.tabs pre:not([style*="block"]) { display: none; }

.prose blockquote {
  margin: 1.4rem 0; padding: .3rem 1rem;
  border-inline-start: 3px solid var(--mw-border); color: var(--mw-muted);
}
.prose blockquote > p { color: inherit; }
.prose blockquote > span { display: block; margin-block-start: .3rem; font-size: .8rem; font-style: normal; }
.prose blockquote.editorial { border-inline-start-color: var(--mw-accent); color: var(--mw-text); font-size: 1.08em; }
.prose blockquote.soft { border: 1px solid var(--mw-border); border-inline-start: 3px solid var(--mw-accent); border-radius: var(--mw-radius-sm); background: var(--mw-accent-soft); color: var(--mw-heading); padding: .8rem 1rem; }
.prose blockquote.pull { border: 0; border-block: 1px solid var(--mw-border); padding: .8rem 0; text-align: center; font-size: 1.15em; color: var(--mw-heading); }
.prose blockquote.policy { border-inline-start: 3px solid var(--mw-muted); background: var(--mw-card-alt); border-radius: var(--mw-radius-sm); padding: .8rem 1rem; }

.prose hr { margin-block: 2rem; }
.prose :is(img, video, figure) { max-width: 100%; }
.prose img { display: block; margin: 1.4rem auto; border-radius: var(--mw-radius-sm); }
.prose figure { margin: 1.4rem 0; }
.prose figure > img { margin-block: 0 .5rem; }
.prose figcaption { color: var(--mw-muted); font-size: .82rem; text-align: center; }
.prose .tr-caption { color: var(--mw-muted); font-size: .8rem; }

.prose .table { max-width: 100%; margin-block: 1.4rem; overflow-x: auto; border-radius: var(--mw-radius-sm); }
.prose table { width: 100%; border-collapse: collapse; font-size: .9rem; }
.prose :is(th, td) { padding: .6rem .8rem; border-block: 1px solid var(--mw-border); text-align: start; vertical-align: top; }
.prose th { color: var(--mw-heading); font-weight: 700; background: var(--mw-card-alt); }
.prose .table.bordered :is(th, td) { border: 1px solid var(--mw-border); }
.prose .table.cborder :is(th, td) { border-inline: 1px solid var(--mw-border); }
.prose .table.noborder :is(th, td) { border: 0; }
.prose .table.stripped tbody tr:nth-child(even) { background: color-mix(in srgb, var(--mw-card-alt) 70%, transparent); }
.prose .table.hovered tbody tr:hover { background: var(--mw-accent-soft); }
.prose .table.sticky thead th { position: sticky; inset-block-start: 0; z-index: 1; }
.prose .table.primary th { background: var(--mw-accent); color: var(--mw-on-accent); }
.prose .table.warning th { background: color-mix(in srgb, var(--mw-warning) 18%, var(--mw-card)); color: var(--mw-heading); }
.prose .table.success th { background: color-mix(in srgb, var(--mw-success) 18%, var(--mw-card)); color: var(--mw-heading); }
.prose .table.error th { background: color-mix(in srgb, var(--mw-error) 16%, var(--mw-card)); color: var(--mw-heading); }
.prose .table.sp5 :is(th, td) { padding: .3rem .4rem; }
.prose .table.sp10 :is(th, td) { padding: .45rem .6rem; }
.prose .table.sp20 :is(th, td) { padding: .8rem 1rem; }
.prose .table.full { width: 100%; }
.prose .table.mh100 { max-height: 100px; overflow-y: auto; }
.prose .table.mh200 { max-height: 200px; overflow-y: auto; }
.prose .table.mh300 { max-height: 300px; overflow-y: auto; }
.prose .table.mhvh { max-height: 70vh; overflow-y: auto; }

/* drop cap */
.prose .dropCap {
  float: inline-start;
  margin: .12em .18em 0 0;
  font-family: var(--mw-font-heading);
  font-size: 3.1em; font-weight: 700; line-height: .82;
  color: var(--mw-accent);
}
html[dir="rtl"] .prose .dropCap { margin: .12em 0 0 .18em; }
.prose p:has(> .dropCap) { min-height: 3.4em; }

/* indent paragraph */
.prose p.pIndent { padding-inline-start: 1.4rem; border-inline-start: 2px solid color-mix(in srgb, var(--mw-accent) 35%, transparent); color: color-mix(in srgb, var(--mw-text) 82%, transparent); }

/* source paragraph */
.prose p.pRef {
  margin-block: 2rem 0; padding: .7rem .9rem;
  border: 1px dashed var(--mw-border); border-radius: var(--mw-radius-sm);
  background: var(--mw-card-alt); color: var(--mw-muted);
  font-size: .8rem; line-height: 1.7;
}

/* notes */
.prose p.note {
  position: relative;
  margin-block: 1.3rem; padding: .85rem 1rem;
  border: 1px solid var(--mw-border); border-inline-start: 3px solid var(--mw-info);
  border-radius: var(--mw-radius-sm); background: var(--mw-card-alt);
  color: color-mix(in srgb, var(--mw-text) 88%, transparent); font-size: .95rem;
}
.prose p.note > b { display: block; margin-block-end: .2rem; color: var(--mw-info); unicode-bidi: plaintext; }
.prose p.note.wr { border-inline-start-color: var(--mw-warning); }
.prose p.note.wr > b { color: var(--mw-warning); }
.prose p.note.qs { border-inline-start-color: var(--mw-tip); }
.prose p.note.qs > b { color: var(--mw-tip); }

/* alerts */
.prose .alert {
  --alert-c: var(--mw-info);
  margin-block: 1.3rem; padding: .85rem 1rem;
  border: 1px solid color-mix(in srgb, var(--alert-c) 24%, var(--mw-border));
  border-inline-start: 4px solid var(--alert-c);
  border-radius: var(--mw-radius-sm);
  background: color-mix(in srgb, var(--alert-c) 7%, var(--mw-card));
  color: color-mix(in srgb, var(--mw-text) 90%, transparent);
  font-size: .95rem;
}
.prose .alert > b { display: block; margin-block-end: .25rem; color: var(--alert-c); unicode-bidi: plaintext; }
.prose .alert.warning { --alert-c: var(--mw-warning); }
.prose .alert.success { --alert-c: var(--mw-success); }
.prose .alert.error { --alert-c: var(--mw-error); }
.prose .alert.tip { --alert-c: var(--mw-tip); }
.prose .alert.question { --alert-c: var(--mw-info); }
.prose .alert.outline { background: transparent; }
.prose .alert > :last-child { margin-bottom: 0; }

/* steps */
.prose ol.steps { list-style: none; counter-reset: mw-step; padding-inline-start: 0; margin-block: 1.4rem; display: grid; gap: .65rem; }
.prose ol.steps > li {
  counter-increment: mw-step;
  position: relative; padding: .7rem .9rem .7rem 3.2rem;
  border: 1px solid var(--mw-border); border-radius: var(--mw-radius-sm);
  background: var(--mw-card); margin: 0;
}
html[dir="rtl"] .prose ol.steps > li { padding: .7rem 3.2rem .7rem .9rem; }
.prose ol.steps > li::before {
  content: counter(mw-step);
  position: absolute; inset-block-start: .55rem; inset-inline-start: .7rem;
  display: grid; place-items: center; width: 1.75rem; height: 1.75rem;
  border-radius: 50%; background: var(--mw-accent); color: var(--mw-on-accent);
  font-size: .82rem; font-weight: 700;
}
.prose ol.steps > li > :last-child { margin-bottom: 0; }

/* key points */
.prose .kp-wrap { display: flex; flex-wrap: wrap; gap: 8px; margin-block: 1.3rem; }
.prose .kp-item {
  display: inline-flex; align-items: center; gap: .35rem;
  padding: .35rem .75rem; border-radius: var(--mw-radius-pill);
  border: 1px solid color-mix(in srgb, var(--mw-accent) 26%, var(--mw-border));
  background: var(--mw-accent-soft); color: var(--mw-heading);
  font-size: .84rem; font-weight: 500;
}
.prose .kp-item::before { content: "✓"; color: var(--mw-accent); font-weight: 700; }

/* details: accordion / spoiler / toc */
.prose details {
  margin-block: .9rem; border: 1px solid var(--mw-border);
  border-radius: var(--mw-radius-sm); background: var(--mw-card);
  overflow: hidden;
}
.prose details > summary {
  display: flex; align-items: center; gap: .5rem;
  padding: .7rem .9rem; cursor: pointer; list-style: none;
  color: var(--mw-heading); font-weight: 600; font-size: .95rem;
  background: color-mix(in srgb, var(--mw-card-alt) 70%, transparent);
  transition: background var(--mw-dur) var(--mw-ease);
}
.prose details > summary::-webkit-details-marker { display: none; }
.prose details > summary::after {
  content: ""; margin-inline-start: auto; width: .5em; height: .5em; flex: 0 0 .5em;
  border-right: 2px solid var(--mw-muted); border-bottom: 2px solid var(--mw-muted);
  transform: rotate(45deg); transition: transform var(--mw-dur) var(--mw-ease);
}
.prose details[open] > summary::after { transform: rotate(-135deg); }
.prose details[open] > summary { border-block-end: 1px solid var(--mw-border); }
.prose details > summary:hover { background: var(--mw-card-alt); }
.prose details > div, .prose details > p { padding: .8rem .95rem; }
.prose details > div > :last-child { margin-bottom: 0; }
.prose details.ac.alt { border-inline-start: 3px solid var(--mw-accent); }
.prose details.ac.alt > summary { background: var(--mw-accent-soft); color: var(--mw-accent); }
.prose details.sp > summary { color: var(--mw-accent); }
.prose .showH { display: grid; gap: 0; margin-block: .8rem; }
.prose .showH > details { margin-block: .45rem; }

/* toc */
.prose details.toc { border-color: color-mix(in srgb, var(--mw-accent) 24%, var(--mw-border)); }
.prose details.toc > summary { background: var(--mw-accent-soft); color: var(--mw-accent); }
.prose .aToc ol { margin: 0; padding-inline-start: 1.2rem; }
.prose .aToc li { margin-block: .3rem; }
.prose .aToc a { font-weight: 500; text-decoration: none; color: var(--mw-text); }
.prose .aToc a:hover { color: var(--mw-accent); }
.prose .aToc .tocI { padding-inline-start: 1rem; font-size: .92em; }

/* spoiler blur */
.prose .spoiler {
  display: inline-block; padding: .05em .35em; border-radius: 4px;
  background: color-mix(in srgb, var(--mw-accent) 12%, var(--mw-card-alt));
  color: transparent; text-shadow: 0 0 8px color-mix(in srgb, var(--mw-text) 75%, transparent);
  cursor: pointer; transition: color var(--mw-dur) var(--mw-ease), text-shadow var(--mw-dur) var(--mw-ease);
}
.prose .spoiler.revealed { color: inherit; text-shadow: none; }

/* mark */
.prose mark {
  padding-inline: .15em; border-radius: 3px;
  background: color-mix(in srgb, var(--mw-accent) 20%, transparent); color: var(--mw-heading);
}

/* buttons & links from the generator */
.prose a.button {
  display: inline-flex; align-items: center; gap: .45rem;
  margin-block: .3rem; padding: .5rem 1rem;
  border: 1px solid var(--mw-accent); border-radius: var(--mw-radius-pill);
  background: var(--mw-accent); color: var(--mw-on-accent);
  font-size: .9rem; font-weight: 600; text-decoration: none;
}
.prose a.button:hover { filter: brightness(.95); color: var(--mw-on-accent); }
.prose a.button.ln { background: transparent; color: var(--mw-accent); }
.prose a.button.ln:hover { background: var(--mw-accent-soft); }

/* download box */
.prose .downloadBox {
  display: flex; align-items: center; gap: .8rem; flex-wrap: wrap;
  margin-block: 1.3rem; padding: .85rem 1rem;
  border: 1px solid var(--mw-border); border-radius: var(--mw-radius-sm); background: var(--mw-card-alt);
}
.prose .downloadBox .icon { color: var(--mw-accent); }

/* related inline box */
.prose .pRelate {
  margin-block: 1.5rem; padding: .9rem 1rem;
  border: 1px solid var(--mw-border); border-radius: var(--mw-radius-sm); background: var(--mw-card-alt);
}
.prose .pRelate > b { display: block; margin-block-end: .4rem; color: var(--mw-heading); }
.prose .pRelate ul { margin: 0; padding-inline-start: 1.2rem; }

/* kbd */
.prose kbd {
  display: inline-block; padding: .1rem .45rem; border: 1px solid var(--mw-border);
  border-radius: 5px; background: var(--mw-card-alt); color: var(--mw-text);
  font: 500 .78em/1.6 var(--mw-font-mono); box-shadow: 0 1px 0 var(--mw-border);
}

/* images & lightbox */
.prose .zmImg { position: relative; cursor: zoom-in; }
.prose .zmImg img { margin-block: 0; }
.lightbox {
  position: fixed; inset: 0; z-index: 3000; display: grid; place-items: center;
  padding: 24px; background: rgb(0 0 0 / .82); opacity: 0; pointer-events: none;
  transition: opacity var(--mw-dur) var(--mw-ease);
}
.lightbox.is-open { opacity: 1; pointer-events: auto; }
.lightbox img { max-width: min(100%, 1200px); max-height: 86vh; border-radius: var(--mw-radius-sm); box-shadow: var(--mw-shadow-lg); }
.lightbox .close { position: absolute; inset-block-start: 16px; inset-inline-end: 16px; width: 40px; height: 40px; border: 0; border-radius: 50%; background: rgb(255 255 255 / .14); color: #fff; display: grid; place-items: center; }

/* =========================================================
   Sidebar widgets
   ========================================================= */
.widget { margin-block-end: 16px; }
.article-side .widget {
  padding: 16px; border: 1px solid var(--mw-border); border-radius: var(--mw-radius);
  background: var(--mw-card); box-shadow: var(--mw-shadow-sm);
}
.widget-title, .article-side .widget h2 {
  margin: 0 0 10px; font-size: .9rem; font-weight: 700; color: var(--mw-heading);
  display: flex; align-items: center; gap: .45rem;
}
.widget-title::before { content: ""; width: 3px; height: 1em; border-radius: 2px; background: var(--mw-accent); }
.widget ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.widget ul li { margin: 0; }
.widget ul li a { display: flex; align-items: center; gap: .5rem; padding: .4rem .5rem; border-radius: var(--mw-radius-sm); color: var(--mw-text); font-size: .85rem; }
.widget ul li a:hover { background: var(--mw-card-alt); color: var(--mw-accent); }
.widget .item-thumbnail { width: 48px; height: 48px; border-radius: var(--mw-radius-sm); object-fit: cover; flex: 0 0 48px; }
.widget .item-snippet { display: block; font-size: .75rem; color: var(--mw-muted); }
.widget .label-size { display: none; }

/* =========================================================
   Footer
   ========================================================= */
.site-footer {
  margin-block-start: clamp(28px, 5vw, 56px);
  border-block-start: 1px solid var(--mw-border);
  background: color-mix(in srgb, var(--mw-card) 55%, transparent);
}
.footer-top { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: clamp(20px, 4vw, 48px); padding-block: clamp(24px, 4vw, 40px); }
.footer-brand p { margin: .6rem 0 0; color: var(--mw-muted); font-size: .84rem; max-width: 40ch; }
.footer-col h3 { font-size: .82rem; letter-spacing: .03em; text-transform: uppercase; color: var(--mw-muted); margin-bottom: .7rem; }
.footer-col ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.footer-col a { color: var(--mw-text); font-size: .86rem; }
.footer-col a:hover { color: var(--mw-accent); }
.footer-bottom {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px;
  padding-block: 14px; border-block-start: 1px solid var(--mw-border);
  font-size: .8rem; color: var(--mw-muted);
}
.footer-social { display: flex; align-items: center; gap: 6px; }
.footer-social a { display: inline-grid; place-items: center; width: 30px; height: 30px; border: 1px solid var(--mw-border); border-radius: 50%; color: var(--mw-muted); background: var(--mw-card); }
.footer-social a:hover { color: var(--mw-accent); border-color: var(--mw-accent); background: var(--mw-accent-soft); }
.footer-social .icon { width: 15px; height: 15px; }

/* back to top */
.to-top {
  position: fixed; inset-block-end: 20px; inset-inline-end: 20px; z-index: 800;
  width: 40px; height: 40px; display: grid; place-items: center;
  border: 1px solid var(--mw-border); border-radius: 50%;
  background: var(--mw-card); color: var(--mw-muted); box-shadow: var(--mw-shadow-md);
  opacity: 0; transform: translateY(8px); pointer-events: none;
  transition: opacity var(--mw-dur) var(--mw-ease), transform var(--mw-dur) var(--mw-ease), color var(--mw-dur) var(--mw-ease);
}
.to-top.is-visible { opacity: 1; transform: none; pointer-events: auto; }
.to-top:hover { color: var(--mw-accent); border-color: var(--mw-accent); }

/* empty / error */
.empty-state, .error-page { text-align: center; padding-block: clamp(48px, 10vw, 110px); }
.error-code { font-size: clamp(3rem, 10vw, 5.5rem); font-weight: 800; color: var(--mw-accent); line-height: 1; margin: 0; }
.error-page p { color: var(--mw-muted); max-width: 44ch; margin-inline: auto; }

/* =========================================================
   Responsive
   ========================================================= */
@media (max-width: 1080px) {
  .page-grid { grid-template-columns: minmax(0, 1fr); }
  .article-side { position: static; }
}
@media (max-width: 900px) {
  .brand-desc { display: none; }
  .cards.cols-3 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .footer-top { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 720px) {
  .featured { grid-template-columns: 1fr; }
  .featured-media { min-height: 0; aspect-ratio: 16 / 9; }
  .cards.cols-3, .cards.cols-2 { grid-template-columns: 1fr; }
  .post-nav { grid-template-columns: 1fr; }
  .article-meta { gap: .45rem .8rem; }
  .prose { font-size: 1rem; }
  .prose h2 { border-block-end: 0; padding-block-end: 0; }
  .footer-top { grid-template-columns: 1fr; }
  .brand-logo { width: 30px; height: 30px; flex-basis: 30px; }
}
@media (max-width: 420px) {
  .header-actions { gap: 2px; }
  .icon-btn { width: 32px; height: 32px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

@media print {
  .site-header, .site-footer, .article-side, .share-bar, .post-nav, .related, .to-top, .reading-progress, .comments-wrap { display: none !important; }
  body { background: #fff; color: #000; }
  .page-grid { display: block; }
  .prose { max-width: none; font-size: 12pt; }
}

/* =========================================================
   Blogger layout mode
   ========================================================= */
body#layout .site-header { position: static; }
body#layout .header-inner { flex-wrap: wrap; }
body#layout .page-grid { display: block; }
body#layout .site-footer { margin: 0; }
body#layout .container { width: auto; }

head.b:template-skin:
body#layout { background: #f6f7f9; padding: 12px; }
body#layout .section { background: #fff; border: 1px solid #e5e7eb; border-radius: 10px; margin-bottom: 12px; }
body#layout .section h4 { background: #eff6ff; color: #1d4ed8; margin: 0 0 8px; padding: 8px; border-radius: 10px 10px 0 0; text-align: center; }
body#layout .widget { border-radius: 8px; }

body.script:
